import json
from tau2.tools import AirlineTools
t = AirlineTools(db_path='/var/tmp/state-travel/tau2/envs/db.json')
for dates in [('2025-05-10','2025-05-13'), ('2025-05-14','2025-05-17'), ('2025-05-21','2025-05-24'), ('2025-05-24','2025-05-27')]:
    sr = t.use_tool('search_car_rentals', {'pickup_location': 'LAS', 'car_class': 'economy', 'pickup_date': dates[0], 'dropoff_date': dates[1]})
    cars = sr.get('result', sr) if isinstance(sr, dict) else sr
    count = len(cars) if isinstance(cars, list) else 'N/A'
    print(f'{dates[0]} to {dates[1]}: {count} results')
    if isinstance(cars, list):
        for c in cars:
            if isinstance(c, dict):
                print(f"  {c.get('car_id','?')} {c.get('company','?')} {c.get('car_class','?')} ${c.get('daily_rate','?')}/day")
print('DONE')

import json
with open('/var/tmp/state-travel/tau2/envs/db.json') as f:
    db = json.load(f)
