import inspect
from tau2.tools import AirlineTools
src = inspect.getsource(AirlineTools)
lines = src.split('\n')
for i, line in enumerate(lines):
    if 'book_car' in line.lower() or 'car_rental' in line.lower():
        start = max(0, i-2)
        end = min(len(lines), i+15)
        print(f'--- Around line {i} ---')
        for j in range(start, end):
            print(f'{j}: {lines[j]}')
        print()

import inspect
from tau2.tools import AirlineTools
src = inspect.getsource(AirlineTools)
lines = src.split('\n')
in_method = False
method_lines = []
for i, line in enumerate(lines):
    if 'def _handle_book_car' in line or 'def book_car' in line:
        in_method = True
    if in_method:
        method_lines.append(f'{i}: {line}')
        if len(method_lines) > 1 and line.strip() and not line.startswith(' ') and not line.startswith('\t'):
            break
        if len(method_lines) > 50:
            break
print('\n'.join(method_lines))

