import inspect
from tau2.tools import AirlineTools
src = inspect.getsource(AirlineTools)
idx = src.find('"book_car_rental"')
if idx < 0:
    idx = src.find("'book_car_rental'")
if idx >= 0:
    print(src[max(0,idx-200):idx+800])
else:
    print('book_car_rental string not found')
    for term in ['book_car', 'car_rent', 'CAR-']:
        i = src.find(term)
        if i >= 0:
            print(f'Found "{term}" at {i}:')
            print(src[max(0,i-50):i+200])
            print()

